@startuml

class Home {
  + Name : string
}

class Department {
  + Name : string
}

class Room {
  + RoomNumber : string
}

class Bed {
  + BedNumber : string
}

class Category {
  + Price : double
}

class Stay {
  + StayType : string
  + Status : string
  + IntakeDate : date
}

class Inhabitant {
  + Name : string
  + ID : string
}

class Registration {
  + RegistrationDate : date
}

class Assessment {
  + NeedsHelp : boolean
}

class WaitingList {
  + Position : int
}

class Proposal {
  + ProposalDate : date
  + IsAccepted : boolean
}

class Invoice {
  + InvoiceNumber : string
  + OutstandingAmount : double
  + Status : string
}

class CreditNote {
  + Amount : double
}

class PaymentEvent {
  + AmountPaid : double
  + PaymentDate : date
}

enum StayType {
  RH
  RNH
  SF
}

Home "1" *-- "1..*" Department
Department "1" *-- "1..*" Room
Room "1" *-- "1..*" Bed
Bed "1" -- "1" Category
Inhabitant "1" -- "1..*" Stay
Stay "1" -- "1" Bed
Stay "1" -- "1" Category
Inhabitant "1" -- "1" Registration
Registration "1" -- "1" Assessment
Assessment "1" -- "1" Stay
Stay "1" -- "0..*" Invoice
Inhabitant "1" -- "0..*" Invoice
Invoice "1" -- "0..*" PaymentEvent
Invoice "1" -- "0..1" CreditNote
Stay "1" -- "0..*" Proposal
Inhabitant "1" -- "0..*" WaitingList
WaitingList "1" -- "1" Stay

@enduml

